"""Append a frozen prospective local-constraint result, preserving its negative."""
from pathlib import Path
from docx import Document
ROOT=Path(__file__).resolve().parents[1]
def main():
 p=ROOT/'paper/MEGA27-23b-50p.docx';d=Document(p)
 title='Prospective local-constraint framing: clean feasibility does not rescue noise recovery'
 assert not any(x.text==title for x in d.paragraphs)
 d.add_heading(title,level=1)
 d.add_paragraph('The previous 48-nucleotide grid contained zero jointly locally feasible long-file identities. A separate frozen design therefore changes the audit framing rather than filtering the old outcomes. Four fresh 128-byte and four fresh 2048-byte identities are generated from seed 728310 before noisy outcomes. Every block carries four nonce trits followed by the previous 48-nucleotide detector/check/padding geometry. All three detectors receive the same 52-nucleotide block length, one outer parity block and three copies. No production codec is changed.')
 d.add_heading('A finite greedy search with visible costs and exclusions',level=2)
 d.add_paragraph('For each block, nonce values zero through eighty define an invertible SHA-256-derived 32-trit payload mask. The first nonce whose low-check, full-check and distance-five sequences jointly pass block GC [.35,.65], every sliding 64-base GC window [.35,.65] at the assembled prefix, and homopolymer length at most two is retained. A block with no candidate excludes the whole identity before noise. Final whole-strand GC [.45,.55] is also required. This is a bounded greedy search, not a proof that no better nonce or code exists. Candidates are computational attempts, not physical synthesized strands. The four emitted nonce bases are charged to every block and copy; search attempts and rejections are recorded separately rather than incorrectly added to transmitted nucleotides.')
 t=d.add_table(rows=1,cols=5);t.style='Light Shading Accent 1'
 for c,v in zip(t.rows[0].cells,['Payload','Identities','Total nt/file','Clean exact','3% exact']):c.text=v
 for row in [('128 bytes','4','4056','8/8','3/8'),('2048 bytes','4','60216','8/8','0/8')]:
  for c,v in zip(t.add_row().cells,row):c.text=v
 d.add_paragraph('Counts in the table apply separately to each of the three detectors. Each identity has two paired noise realizations, so eight trials are four identities, not eight independent messages. The entire grid has 96 trials including clean and noisy conditions. Every noisy long-file trial is a loud failure; five of eight noisy small-file trials per detector are loud failures. No silent wrong occurs in this finite grid, which cannot establish a never-wrong guarantee.')
 d.add_paragraph('All eight identities pass the prospective constraints, with zero identity exclusions. Small-file candidate attempts are 26, 29, 26 and 27 for 26 emitted blocks each; long-file attempts are 402, 389, 389 and 387 for 386 emitted blocks each. Thus 27 candidate rejections are charged as computational search work across 1648 accepted blocks. Payload densities are 1024/4056 = .252466 and 16384/60216 = .272087 bits per transmitted nucleotide at three copies. The clean feasibility result does not imply robust recovery: the long-file three-percent outcome is zero exact recovery for all detectors.')
 d.add_heading('A nonce is a new failure surface, not free protection',level=2)
 d.add_paragraph('Decoding recovers the nonce from its four nucleotide prefix, checks the following core under that prefix seed, then removes the corresponding payload mask. Corrupted nonce bases can select the wrong mask even when a core detector accepts; the global checksum and byte validation remain fallible safeguards. The earlier distance-five proof applies to strict substitutions within an isolated seeded 48-nucleotide core. It does not extend to this 52-nucleotide frame with nonce corruption, boundary effects, whole-file parity or recovery. We therefore claim neither the old detection guarantee nor physical synthesis feasibility for the new codec.')
 d.add_paragraph('This pivot separates locally compliant clean sequence construction from noisy file recovery. It improves the former under the stated finite software gates but leaves the latter negative at the tested long-file rate. The new messages and geometry differ from the earlier stripe grid, so its 16/16 outcome cannot be treated as a paired baseline for this 0/8 result. Primer compatibility, motifs, physical oligo segmentation, indexing, indels, dropout, amplification and molecular-copy effects remain absent. There is no optimized or externally validated frontier. The frozen plan, candidate ledger, complete trial outcomes and tests are stored in experiments/local_constrained_plan.json, results/local_constrained_audit.json and tests/test_local_constrained_audit.py.')
 d.save(p)
if __name__=='__main__':main()
